#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    int maximumGain(string s, int x, int y) {
        string first_pair = "ab", second_pair = "ba";
        int first_val = x, second_val = y;
        if (y > x) {
            first_pair = "ba";
            second_pair = "ab";
            first_val = y;
            second_val = x;
        }

        int ans = 0;
        string st1 = "";
        for (char c : s) {
            if (!st1.empty() && st1.back() == first_pair[0] && c == first_pair[1]) {
                st1.pop_back();
                ans += first_val;
            } else {
                st1.push_back(c);
            }
        }

        string st2 = "";
        for (char c : st1) {
            if (!st2.empty() && st2.back() == second_pair[0] && c == second_pair[1]) {
                st2.pop_back();
                ans += second_val;
            } else {
                st2.push_back(c);
            }
        }
        return ans;
    }
};

class Solution {
    public int maximumGain(String s, int x, int y) {
        String firstPair = "ab", secondPair = "ba";
        int firstVal = x, secondVal = y;
        if (y > x) {
            firstPair = "ba";
            secondPair = "ab";
            firstVal = y;
            secondVal = x;
        }

        int ans = 0;
        StringBuilder st1 = new StringBuilder();
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            int len = st1.length();
            if (len > 0 && st1.charAt(len - 1) == firstPair.charAt(0) && c == firstPair.charAt(1)) {
                st1.deleteCharAt(len - 1);
                ans += firstVal;
            } else {
                st1.append(c);
            }
        }

        StringBuilder st2 = new StringBuilder();
        for (int i = 0; i < st1.length(); ++i) {
            char c = st1.charAt(i);
            int len = st2.length();
            if (len > 0 && st2.charAt(len - 1) == secondPair.charAt(0) && c == secondPair.charAt(1)) {
                st2.deleteCharAt(len - 1);
                ans += secondVal;
            } else {
                st2.append(c);
            }
        }
        return ans;
    }
}

