var maximumGain = function(s, x, y) {
    let firstPair = "ab", secondPair = "ba";
    let firstVal = x, secondVal = y;
    if (y > x) {
        firstPair = "ba";
        secondPair = "ab";
        firstVal = y;
        secondVal = x;
    }

    let ans = 0;
    const st1 = [];
    for (const c of s) {
        if (st1.length > 0 && st1[st1.length - 1] === firstPair[0] && c === firstPair[1]) {
            st1.pop();
            ans += firstVal;
        } else {
            st1.push(c);
        }
    }

    const st2 = [];
    for (const c of st1) {
        if (st2.length > 0 && st2[st2.length - 1] === secondPair[0] && c === secondPair[1]) {
            st2.pop();
            ans += secondVal;
        } else {
            st2.push(c);
        }
    }
    return ans;
};
